WITH "__duckstream_0" AS ((SELECT t.c0 AS c0, t.c1 AS c1, t.c3 AS c2, t.c4 AS c3, t.c5 AS c4, t.c17 AS c5, t.c6 AS c6, t.c7 AS c7, 'home' AS c8, t.c8 AS c9, t.c9 AS c10 FROM (SELECT "id" AS c0, "phase_id" AS c1, "round" AS c2, "day" AS c3, "kickoff" AS c4, "played" AS c5, "home_id" AS c6, "away_id" AS c7, "home_score" AS c8, "away_score" AS c9, "home_aet" AS c10, "away_aet" AS c11, "home_pen" AS c12, "away_pen" AS c13, "stadium_id" AS c14, "referee_id" AS c15, "attendance" AS c16, "fixture_available" AS c17 FROM "source_game") t) UNION ALL (SELECT t.c0 AS c0, t.c1 AS c1, t.c3 AS c2, t.c4 AS c3, t.c5 AS c4, t.c17 AS c5, t.c7 AS c6, t.c6 AS c7, 'away' AS c8, t.c9 AS c9, t.c8 AS c10 FROM (SELECT "id" AS c0, "phase_id" AS c1, "round" AS c2, "day" AS c3, "kickoff" AS c4, "played" AS c5, "home_id" AS c6, "away_id" AS c7, "home_score" AS c8, "away_score" AS c9, "home_aet" AS c10, "away_aet" AS c11, "home_pen" AS c12, "away_pen" AS c13, "stadium_id" AS c14, "referee_id" AS c15, "attendance" AS c16, "fixture_available" AS c17 FROM "source_game") t)),
"__duckstream_1" AS (SELECT ((t.c6 || ':') || t.c0) AS c0, t.c6 AS c1, t.c0 AS c2, t.c8 AS c3, t.c7 AS c4, t.c18 AS c5, t.c12 AS c6, t.c15 AS c7, t.c2 AS c8, t.c3 AS c9, t.c4 AS c10, t.c9 AS c11, t.c10 AS c12, CAST(CASE WHEN (NOT t.c4) THEN '' WHEN (t.c9 > t.c10) THEN 'w' WHEN (t.c9 < t.c10) THEN 'l' ELSE 'd' END AS VARCHAR) AS c13, t.c16 AS c14, t.c11 AS c15, COALESCE(t.c16, 'professional') AS c16, t.c5 AS c17 FROM (SELECT t.c0 AS c0, t.c1 AS c1, t.c2 AS c2, t.c3 AS c3, t.c4 AS c4, t.c5 AS c5, t.c6 AS c6, t.c7 AS c7, t.c8 AS c8, t.c9 AS c9, t.c10 AS c10, t.c13 AS c11, t.c14 AS c12, t.c15 AS c13, t.c16 AS c14, t.c17 AS c15, t.c18 AS c16, t.c11 AS c17, t.c12 AS c18 FROM (SELECT t.c6 AS c0, t.c7 AS c1, t.c8 AS c2, t.c9 AS c3, t.c10 AS c4, t.c11 AS c5, t.c12 AS c6, t.c13 AS c7, t.c14 AS c8, t.c15 AS c9, t.c16 AS c10, t.c17 AS c11, t.c18 AS c12, t.c0 AS c13, t.c1 AS c14, t.c2 AS c15, t.c3 AS c16, t.c4 AS c17, t.c5 AS c18 FROM (SELECT l.c0 AS c0, l.c1 AS c1, l.c2 AS c2, l.c3 AS c3, l.c4 AS c4, l.c5 AS c5, r.c0 AS c6, r.c1 AS c7, r.c2 AS c8, r.c3 AS c9, r.c4 AS c10, r.c5 AS c11, r.c6 AS c12, r.c7 AS c13, r.c8 AS c14, r.c9 AS c15, r.c10 AS c16, r.c11 AS c17, r.c12 AS c18 FROM (SELECT t.c3 AS c0, t.c4 AS c1, t.c5 AS c2, t.c0 AS c3, t.c1 AS c4, t.c2 AS c5 FROM (SELECT l.c0 AS c0, l.c1 AS c1, l.c2 AS c2, r.c0 AS c3, r.c1 AS c4, r.c2 AS c5 FROM (SELECT "id" AS c0, "full_name" AS c1, "category_id" AS c2 FROM "source_championship") l INNER JOIN (SELECT "id" AS c0, "championship_id" AS c1, "name" AS c2 FROM "source_phase") r ON (l.c0 = r.c1)) t) l INNER JOIN (SELECT t.c2 AS c0, t.c3 AS c1, t.c4 AS c2, t.c5 AS c3, t.c6 AS c4, t.c7 AS c5, t.c8 AS c6, t.c9 AS c7, t.c10 AS c8, t.c11 AS c9, t.c12 AS c10, t.c0 AS c11, t.c1 AS c12 FROM (SELECT l.c0 AS c0, l.c1 AS c1, r.c0 AS c2, r.c1 AS c3, r.c2 AS c4, r.c3 AS c5, r.c4 AS c6, r.c5 AS c7, r.c6 AS c8, r.c7 AS c9, r.c8 AS c10, r.c9 AS c11, r.c10 AS c12 FROM (SELECT "id" AS c0, "name" AS c1 FROM "source_team") l INNER JOIN (SELECT v.c0 AS c0, v.c1 AS c1, v.c2 AS c2, v.c3 AS c3, v.c4 AS c4, v.c5 AS c5, v.c6 AS c6, v.c7 AS c7, v.c8 AS c8, v.c9 AS c9, v.c10 AS c10 FROM "__duckstream_0" v) r ON (l.c0 = r.c7)) t) r ON (l.c0 = r.c1)) t) t) t)
SELECT CAST(result.c0 AS VARCHAR) AS "id", CAST(result.c1 AS VARCHAR) AS "team_id", CAST(result.c2 AS VARCHAR) AS "game_id", CAST(result.c3 AS VARCHAR) AS "side", CAST(result.c4 AS VARCHAR) AS "opponent_id", CAST(result.c5 AS VARCHAR) AS "opponent_name", CAST(result.c6 AS VARCHAR) AS "championship_id", CAST(result.c7 AS VARCHAR) AS "championship_name", CAST(result.c8 AS VARCHAR) AS "day", CAST(result.c9 AS VARCHAR) AS "kickoff", CAST(result.c10 AS BOOLEAN) AS "played", CAST(result.c11 AS INTEGER) AS "goals_for", CAST(result.c12 AS INTEGER) AS "goals_against", CAST(result.c13 AS VARCHAR) AS "result", CAST(result.c14 AS VARCHAR) AS "category_id", CAST(result.c15 AS VARCHAR) AS "phase_key", CAST(result.c16 AS VARCHAR) AS "category_key", CAST(result.c17 AS BOOLEAN) AS "fixture_available" FROM (SELECT v.c0 AS c0, v.c1 AS c1, v.c2 AS c2, v.c3 AS c3, v.c4 AS c4, v.c5 AS c5, v.c6 AS c6, v.c7 AS c7, v.c8 AS c8, v.c9 AS c9, v.c10 AS c10, v.c11 AS c11, v.c12 AS c12, v.c13 AS c13, v.c14 AS c14, v.c15 AS c15, v.c16 AS c16, v.c17 AS c17 FROM "__duckstream_1" v) result;
